function validate([arrays]) {
  if (!Array.isArray(arrays) || arrays.length < 2 || arrays.length > 100000) return 'arrays needs 2 to 10^5 arrays.';
  let total = 0;
  for (const row of arrays) {
    if (!Array.isArray(row) || row.length < 1 || row.length > 500) return 'Each array has 1 to 500 integers.';
    total += row.length;
    for (let j = 0; j < row.length; j++) {
      if (!Number.isInteger(row[j]) || row[j] < -10000 || row[j] > 10000) return 'Each integer is between -10^4 and 10^4.';
      if (j > 0 && row[j] < row[j - 1]) return 'Each array must be sorted in ascending order.';
    }
  }
  if (total > 100000) return 'All arrays together hold at most 10^5 integers.';
  return null;
}

