function maxDistance(arrays) {
  let low = arrays[0][0];
  let high = arrays[0][arrays[0].length - 1];
  let best = 0;
  for (let i = 1; i < arrays.length; i++) {
    const first = arrays[i][0];
    const last = arrays[i][arrays[i].length - 1];
    best = Math.max(best, last - low, high - first);
    low = Math.min(low, first);
    high = Math.max(high, last);
  }
  return best;
}

