function maxDistance(arrays) {
  // Try every pair of values taken from two different arrays.
  let best = 0;
  for (let i = 0; i < arrays.length; i++)
    for (let j = i + 1; j < arrays.length; j++)
      for (const a of arrays[i])
        for (const b of arrays[j]) best = Math.max(best, Math.abs(a - b));
  return best;
}

