function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const m = large ? 1500 + pick(500) : 2 + pick(4);
  const span = large ? 10000 : 6 + pick(10);
  const arrays = [];
  for (let i = 0; i < m; i++) {
    const length = large ? 1 + pick(9) : 1 + pick(4);
    const row = Array.from({ length }, () => pick(2 * span + 1) - span);
    arrays.push(row.sort((a, b) => a - b));
  }
  // Sometimes one array holds both extremes, the case a naive global min/max gets wrong.
  if (rand() < 0.4) {
    const row = arrays[pick(m)];
    row[0] = -span;
    row[row.length - 1] = span;
    row.sort((a, b) => a - b);
  }
  return [arrays];
}
